  }


  /** helper function to check PreparationAssessment_acquisition_process_preparation_assessment's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param preparation_facts method that will be called with the value of the outgoing data
   *        port 'preparation_facts'.
   */
  def check_concrete_output(preparation_facts: EIT_Acquisition_Supervisor.PreparationFacts.Type => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val preparation_factsValue: EIT_Acquisition_Supervisor.PreparationFacts.Type = get_preparation_facts().get
    if(!preparation_facts(preparation_factsValue)) {
