  // getter for out DataPort
  def get_preparation_facts(): Option[EIT_Acquisition_Supervisor.PreparationFacts.Type] = {
    val value: Option[EIT_Acquisition_Supervisor.PreparationFacts.Type] = get_preparation_facts_payload() match {
